      const behaviour = {
        parents: particle,
      };

      particle.behaviours = [behaviour];

      particle.removeBehaviour({});

      expect(particle.behaviours).toEqual([behaviour]);
      expect(behaviour.parents).toBe(particle);
    });
  });
});

